import data from '@/data/playlist.generated.json';
import type { Playlist, PlaylistTrack } from '@/types';

// Playlist data generated by `npm run playlist:sync`
export const playlist: Playlist = data;

const byUri = new Map(playlist.tracks.map((t) => [t.uri, t]));

export const findTrack = (uri: string | null): PlaylistTrack | undefined => (uri ? byUri.get(uri) : undefined);

export const trackIndex = (uri: string | null) => playlist.tracks.findIndex((t) => t.uri === uri);

// Link to the song on Spotify
export const trackUrl = (track: PlaylistTrack) => `https://open.spotify.com/track/${track.id}`;

export const totalDurationMs = playlist.tracks.reduce((sum, t) => sum + t.durationMs, 0);

// 3:07 or 1:02:45
export function formatDuration(ms: number): string {
  const total = Math.max(0, Math.round(ms / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = String(total % 60).padStart(2, '0');
  return h ? `${h}:${String(m).padStart(2, '0')}:${s}` : `${m}:${s}`;
}
